#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

int main(int argc, char *argv[])
{
    if (argc != 3) {
        puts("USAGE");
        return 0;
    }

    char *endptr;
    long shift = strtol(argv[1], &endptr, 10);
    if (*endptr != '\0') {
        puts("USAGE");
        return 0;
    }
    shift %= 26;
    if (shift < 0)
        shift += 26;

    const char *text = argv[2];
    size_t len = strlen(text);
    if (len > 1024) {
        puts("USAGE");
        return 0;
    }

    for (size_t i = 0; i < len; ++i) {
        unsigned char c = (unsigned char)text[i];
        if (isupper(c)) {
            putchar((char)('A' + (c - 'A' + shift) % 26));
        } else if (islower(c)) {
            putchar((char)('a' + (c - 'a' + shift) % 26));
        } else {
            putchar(c);
        }
    }
    putchar('\n');
    return 0;
}
